// Assign load addresses to sections with alignment
const secs=[[".text", 4096, 16], [".rodata", 1024, 8], [".data", 512, 4]];
let addr=0x08000000;
const out=secs.map(s=>{addr=Math.ceil(addr/s[2])*s[2];const a=addr;addr+=s[1];return s[0]+' @ 0x'+a.toString(16);});
console.log(out.join('\n'));

